import{_ as t,C as r,c as o,o as h,j as l,ak as d,a as i,G as s}from"./chunks/framework.HpAH9DIy.js";const P=JSON.parse('{"title":"日常任务说明","description":"","frontmatter":{},"headers":[],"relativePath":"Features/DailyTasks.md","filePath":"zh/Features/DailyTasks.md","lastUpdated":1773811469000}'),u={name:"Features/DailyTasks.md"},n={id:"日常任务说明",tabindex:"-1"};function c(b,a,q,m,k,f){const e=r("Badge");return h(),o("div",null,[l("h1",n,[a[0]||(a[0]=i("日常任务说明")),s(e,{type:"tip",text:"参考"}),a[1]||(a[1]=i()),a[2]||(a[2]=l("a",{class:"header-anchor",href:"#日常任务说明","aria-label":'Permalink to "日常任务说明<Badge type="tip" text="参考" />"'},"​",-1))]),a[3]||(a[3]=d('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本文汇总功能介绍中偏“日常一条龙”的任务，用于快速理解每类任务的适用场景和注意事项。</p></div><h2 id="一、启动-关闭游戏" tabindex="-1">一、启动 / 关闭游戏 <a class="header-anchor" href="#一、启动-关闭游戏" aria-label="Permalink to &quot;一、启动 / 关闭游戏&quot;">​</a></h2><h3 id="启动-biubiu-加速器" tabindex="-1">启动 biubiu 加速器 <a class="header-anchor" href="#启动-biubiu-加速器" aria-label="Permalink to &quot;启动 biubiu 加速器&quot;">​</a></h3><ul><li>需要保证想加速的区服在首页第一个位置，否则可能加速错误。</li><li>该任务只负责加速，不负责启动游戏。</li></ul><h3 id="启动游戏" tabindex="-1">启动游戏 <a class="header-anchor" href="#启动游戏" aria-label="Permalink to &quot;启动游戏&quot;">​</a></h3><ol><li>点击任务旁齿轮选择服务器。</li><li>支持如鸢官服、<code>TAP</code> 服、九游服等，以及代号鸢港服 / 台服。</li><li>启动前确保游戏未运行，否则可能卡住。</li></ol><h3 id="关闭游戏" tabindex="-1">关闭游戏 <a class="header-anchor" href="#关闭游戏" aria-label="Permalink to &quot;关闭游戏&quot;">​</a></h3><ul><li>直接关闭游戏端。</li></ul><h2 id="二、鸢报相关" tabindex="-1">二、鸢报相关 <a class="header-anchor" href="#二、鸢报相关" aria-label="Permalink to &quot;二、鸢报相关&quot;">​</a></h2><h3 id="鸢报四连-日常专用" tabindex="-1">鸢报四连（日常专用） <a class="header-anchor" href="#鸢报四连-日常专用" aria-label="Permalink to &quot;鸢报四连（日常专用）&quot;">​</a></h3><ul><li>适合日常一条龙里的单次执行。</li><li>仅在四种鸢报次数都充足时更稳妥。</li></ul><h3 id="小道消息-日常专用" tabindex="-1">小道消息（日常专用） <a class="header-anchor" href="#小道消息-日常专用" aria-label="Permalink to &quot;小道消息（日常专用）&quot;">​</a></h3><ul><li>主要用于衔接日常一条龙内的单次流程。</li></ul><h3 id="鸢报四合一" tabindex="-1">鸢报四合一 <a class="header-anchor" href="#鸢报四合一" aria-label="Permalink to &quot;鸢报四合一&quot;">​</a></h3><ul><li>可循环执行。</li><li>会轮流处理激活事件，并自动跳过鸟食不足事件。</li><li>决策事件和无建材箱的物资支援会被强制做掉。</li></ul><h3 id="待办公务" tabindex="-1">待办公务 <a class="header-anchor" href="#待办公务" aria-label="Permalink to &quot;待办公务&quot;">​</a></h3><ul><li>循环任务。</li><li>可选是否做物资支援、决策事件和战斗。</li></ul><h2 id="三、历练" tabindex="-1">三、历练 <a class="header-anchor" href="#三、历练" aria-label="Permalink to &quot;三、历练&quot;">​</a></h2><ul><li>铜钱历练：可选级别与次数。</li><li>经验历练：可选级别与次数。</li><li>修为历练：可选类别、级别与次数。</li></ul><h2 id="四、据点" tabindex="-1">四、据点 <a class="header-anchor" href="#四、据点" aria-label="Permalink to &quot;四、据点&quot;">​</a></h2><h3 id="据点日常" tabindex="-1">据点日常 <a class="header-anchor" href="#据点日常" aria-label="Permalink to &quot;据点日常&quot;">​</a></h3><ul><li>属于日常任务。</li><li>“强制派遣”表示即使当前派遣未结束，也会召回后重新派遣。</li><li>不建议和普通派遣同时勾选。</li></ul><h3 id="据点商人购物" tabindex="-1">据点商人购物 <a class="header-anchor" href="#据点商人购物" aria-label="Permalink to &quot;据点商人购物&quot;">​</a></h3><ul><li>自动购买并免费刷新 <code>1</code> 次。</li><li>如果要买多个商品，需要添加多个任务。</li></ul><h3 id="派遣四合一" tabindex="-1">派遣四合一 <a class="header-anchor" href="#派遣四合一" aria-label="Permalink to &quot;派遣四合一&quot;">​</a></h3><ul><li>循环任务。</li><li>各据点派遣阵容可自定义。</li><li>强制派遣逻辑与据点日常一致。</li></ul><h3 id="据点情报二合一" tabindex="-1">据点情报二合一 <a class="header-anchor" href="#据点情报二合一" aria-label="Permalink to &quot;据点情报二合一&quot;">​</a></h3><ul><li>循环任务。</li><li>无论是否有月卡，未完成的情报都会尝试通过自动走格子完成。</li></ul><h2 id="五、兰台与地宫" tabindex="-1">五、兰台与地宫 <a class="header-anchor" href="#五、兰台与地宫" aria-label="Permalink to &quot;五、兰台与地宫&quot;">​</a></h2><h3 id="白鹄扫荡" tabindex="-1">白鹄扫荡 <a class="header-anchor" href="#白鹄扫荡" aria-label="Permalink to &quot;白鹄扫荡&quot;">​</a></h3><ul><li>日常任务，只负责扫荡。</li></ul><h3 id="地宫助手" tabindex="-1">地宫助手 <a class="header-anchor" href="#地宫助手" aria-label="Permalink to &quot;地宫助手&quot;">​</a></h3><ul><li>循环任务，目前仍偏试用版。</li><li>优先打未通关关卡，全通后默认扫荡。</li><li>默认扫荡 <code>10</code> 次，不足时自动停止。</li></ul><h2 id="六、其他日常任务" tabindex="-1">六、其他日常任务 <a class="header-anchor" href="#六、其他日常任务" aria-label="Permalink to &quot;六、其他日常任务&quot;">​</a></h2><ul><li>领月卡福利：可选都领或只领商店免费 <code>20</code> 体力。</li><li>日常收尾 <code>V2</code>：包括相见、家具互动、首位密探升级、每日分享、送礼等。</li><li>每日进膳：自动领取陈登的小点心。</li><li>红点消除助手：处理心纸居读信、密探传闻等。</li><li>百宝箱：补充一些杂项操作。</li><li>观星：可选星图与方式。</li></ul>',35))])}const p=t(u,[["render",c]]);export{P as __pageData,p as default};
